def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The template is the largest 4-connected component of non-background cells.
    cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] != 0}
    comps = []
    while cells:
        seed = cells.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)
    template = max(comps, key=len)
    r0 = min(r for r,c in template); r1 = max(r for r,c in template)
    c0 = min(c for r,c in template); c1 = max(c for r,c in template)
    pattern = [[g[r0+r][c0+c] for c in range(c1-c0+1)] for r in range(r1-r0+1)]
    markers = [(r,c) for comp in comps if comp is not template for r,c in comp]
    # Restore the template source and stamp the same pattern centered on each singleton marker.
    for r,c in markers:
        top = r - len(pattern)//2
        left = c - len(pattern[0])//2
        for dr,row in enumerate(pattern):
            for dc,value in enumerate(row):
                if value != 0:
                    g[top+dr][left+dc] = value
    return g
